#include <iostream>

using namespace std;

int main()
{
    double c, f;
    cout << "Enter temperature in F: ";
    cin >> f;

    c = (f - 32) * 5 / 9;

    cout << f << "F = " << c << "C!" << endl;

    return 0;
}

#include <iostream>
using namespace std;

int main()
{
    int number;

    cout << "Enter a number: ";
    cin >> number;

    if (number > 0)
    {
        cout << "Positive" << endl;
    }
    else
    {
        cout << "Not positive" << endl;
    }
}
